#!/usr/bin/env python3
"""Build the project registry from the module entries. Adapted from the hydroacoustics build_registry.py (23 Oct 2026). 25 Oct 2026.

  * modules/<module>/entries.yaml is generated by backfill_registry.py from records (never typed-in hashes or quotes).
  * This script resolves each path, lists each file with bytes and SHA-256 (modules/<module>/manifests/<id>.tsv.gz),
    checks again that each cited evidence line still holds its quote, and writes modules/<module>/REGISTRY.json and the
    merged registry REGISTRY.json. A missing path, a changed evidence line or an unknown defect id is an ERROR; the build fails.
  * Exchange-folder files are not hashed again: bytes and SHA-256 come from data_homes/exchange_inventory.json.gz
    (SHA256SUMS files, or a hash of each file < 1 GB that has no SHA256SUMS entry). Files >= 1 GB with no checksum are listed, not hashed.
  * Roots point only to the repository, the exchange folder, ~/Downloads data homes, the external drive, git or a Drive id.
  * Phase 2 (26 Oct 2026), module hydroacoustics: the hydro exchange inventory (data_homes/exchange_inventory_hydroacoustics.json.gz)
    is read too; an EX entry can name one file or give exchange_file_list; a DL entry with hash "stat+lt1g" also hashes files < 1 GB
    that have no SHA256SUMS entry; a GIT entry with git_path lists the files of that path at the commit and hashes each blob;
    modules/<module>/constants.json is copied to module_constants in the merged registry.
Usage: python3 build_registry.py [--no-hash] [--repo <repo top>]
"""
import argparse, collections, gzip, hashlib, json, os, re, subprocess, sys, time
from pathlib import Path
import yaml

HERE = Path(__file__).resolve().parent
WORKN = "Claude Science Project Sep 29"
STATUS = ["CURRENT", "CURRENT_WITH_CAVEATS", "KNOWN_DEFECT", "SUPERSEDED", "WITHDRAWN", "PENDING_RULING", "UNCHECKED"]
WS = re.compile("/" + "workspaces/" + "|" + "/" + r"\.claude-" + "science/")


def sha256(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 22), b""):
            h.update(b)
    return h.hexdigest()


def git(top, *a):
    env = {**os.environ, "GIT_CONFIG_GLOBAL": "/dev/null"}
    return subprocess.run(["git", *a], cwd=top, capture_output=True, text=True, env=env).stdout


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--no-hash", action="store_true"); ap.add_argument("--repo")
    a = ap.parse_args()
    top = Path(a.repo or git(HERE, "rev-parse", "--show-toplevel").strip()).resolve()
    roots = json.load(open(HERE / "roots.json"))["roots"]
    for k in list(roots):
        if os.environ.get(f"PROJECT_ROOT_{k}"):
            roots[k] = os.environ[f"PROJECT_ROOT_{k}"]
    rpath = {"REPO": top, "WORK": top / WORKN, **{k: Path(v) for k, v in roots.items() if v and not v.startswith("<")}}
    spec = json.load(open(HERE / "registry_spec.json"))
    defect_ids = {d["id"] for d in spec["defects"]}
    tracked = [p for p in git(top, "ls-files", "-z").split("\0") if p]
    inv = json.load(gzip.open(HERE / "data_homes" / "exchange_inventory.json.gz", "rt"))
    hinv = HERE / "data_homes" / "exchange_inventory_hydroacoustics.json.gz"
    if hinv.exists():
        inv["files"] = inv["files"] + json.load(gzip.open(hinv, "rt"))["files"]
    module_constants = {}
    errors, merged, covered = [], [], set()
    t0 = time.time()
    for mod in spec["modules"]:
        mdir = HERE / "modules" / mod
        ent = yaml.safe_load(open(mdir / "entries.yaml"))
        (mdir / "manifests").mkdir(exist_ok=True)
        out = []
        for e in ent["entries"]:
            r = dict(e)
            root, _, rel = e["path"].partition(":")
            rows, note = None, None
            try:
                if root in ("REPO", "WORK"):
                    base = "" if root == "REPO" else WORKN + "/"
                    full = (base + rel).rstrip("/")
                    if e.get("file_list"):
                        files = [(base + f) if root == "WORK" and not f.startswith(WORKN) else f for f in e["file_list"]]
                        files = [f for f in files]
                    elif full == "":
                        raise ValueError("empty repository path without a file list")
                    else:
                        files = [p for p in tracked if p == full or p.startswith(full + "/")]
                    if not files:
                        raise FileNotFoundError(f"{e['path']}: no tracked file")
                    rows = []
                    for f in sorted(files):
                        p = top / f
                        if not p.exists():
                            raise FileNotFoundError(f)
                        rows.append((f, p.stat().st_size, "" if a.no_hash else sha256(p)))
                        covered.add(f)
                elif root == "EX":
                    pre = e.get("exchange_prefix")
                    if pre and e.get("exchange_file_list"):
                        want = {pre + "/" + f for f in e["exchange_file_list"]}
                        sel = [x for x in inv["files"] if "bytes" in x and x["rel"] in want]
                        if len(sel) != len(want):
                            raise FileNotFoundError(f"{e['path']}: {len(want) - len(sel)} listed files not in the exchange inventory")
                    else:
                        sel = [x for x in inv["files"] if "bytes" in x and (x["rel"] == pre or x["rel"].startswith(pre + "/") if not e.get("exchange_top_files_only") else (x["rel"].startswith(pre) and x["rel"].count("/") == 1))] if pre else []
                    if pre and not sel:
                        raise FileNotFoundError(f"{e['path']}: no file in the exchange inventory")
                    rows = [(x["rel"], x["bytes"], x.get("sha256") or "", x.get("sha_source", "")) for x in sel] if pre else None
                    if rows is not None:
                        r["not_hashed"] = [x["rel"] for x in sel if not x.get("sha256")]
                    else:
                        note = e.get("hash_note", "not hashed")
                elif root == "XDRIVE" and e.get("file_rows"):   # external drive (not mounted): rows from the registry record
                    rows = [(f, b or 0, sh or "", src) for f, b, sh, src in e["file_rows"]]
                    r["not_hashed"] = [x[0] for x in rows if not x[2]]
                    r.pop("file_rows", None)
                elif root == "GIT" and e.get("git_path"):
                    ref = rel.split("@", 1)[1]
                    ls = git(top, "ls-tree", "-r", "-z", "--full-tree", ref, "--", e["git_path"]).split("\0")
                    blobs = [(l.split("\t", 1)[1], l.split()[2]) for l in ls if l and l.split()[1] == "blob"]
                    if not blobs:
                        raise FileNotFoundError(f"{e['git_path']}: no file at {ref}")
                    env = {**os.environ, "GIT_CONFIG_GLOBAL": "/dev/null"}
                    pr = subprocess.run(["git", "cat-file", "--batch"], cwd=top, input="".join(o + "\n" for _, o in blobs).encode(), capture_output=True, env=env).stdout
                    rows, pos = [], 0
                    for f, o in blobs:
                        hdr_end = pr.index(b"\n", pos); size = int(pr[pos:hdr_end].split()[2]); data = pr[hdr_end + 1: hdr_end + 1 + size]
                        pos = hdr_end + 1 + size + 1
                        rows.append((f, size, "" if a.no_hash else hashlib.sha256(data).hexdigest()))
                elif root == "DL" and e.get("hash") in ("stat", "stat+lt1g"):
                    p = rpath["DL"] / rel
                    if not p.exists():
                        raise FileNotFoundError(str(p))
                    sums = {}
                    for s in p.rglob("SHA256SUMS*"):
                        for line in s.read_text(errors="replace").splitlines():
                            q = line.split(None, 1)
                            if len(q) == 2 and len(q[0]) == 64:
                                sums[str((s.parent / q[1].lstrip("*").strip()).resolve())] = q[0]
                    rows = [(str(f.relative_to(rpath["DL"])), f.stat().st_size, sums.get(str(f.resolve()), ""), "SHA256SUMS" if str(f.resolve()) in sums else "not hashed")
                            for f in (sorted(p.rglob("*")) if p.is_dir() else [p]) if f.is_file()]
                    if e.get("hash") == "stat+lt1g" and not a.no_hash:
                        rows = [(x[0], x[1], sha256(rpath["DL"] / x[0]), "computed " + time.strftime("%Y-%m-%d")) if not x[2] and x[1] < (1 << 30) else x for x in rows]
                    r["not_hashed"] = [x[0] for x in rows if not x[2]]
                else:
                    note = e.get("hash_note", "not hashed")
                if rows is not None:
                    mf = mdir / "manifests" / f"{e['id']}.tsv.gz"
                    with gzip.GzipFile(mf, "wb", mtime=0) as fh:
                        cols = "relpath\tbytes\tsha256" + ("\tsha_source" if rows and len(rows[0]) == 4 else "")
                        fh.write((cols + "\n" + "".join("\t".join(map(str, x)) + "\n" for x in rows)).encode())
                    body = "\n".join("\t".join(map(str, x[:3])) for x in rows).encode()
                    r.update(n_files=len(rows), bytes=sum(x[1] for x in rows), manifest=f"modules/{mod}/manifests/{e['id']}.tsv.gz",
                             manifest_sha256=hashlib.sha256(body).hexdigest())
                else:
                    r.update(n_files=None, bytes=None, manifest=None, manifest_sha256=None, hash_note=note)
                for ev in e.get("status_evidence", []):
                    src = ev.get("source", "")
                    m = re.match(r"^(WORK|REPO):(.*):(\d+)$", src)
                    if m and ev.get("quote"):
                        p = (top / WORKN if m.group(1) == "WORK" else top) / m.group(2)
                        line = p.read_text(errors="replace").splitlines()[int(m.group(3)) - 1].strip()
                        if WS.sub("", line)[:60] != WS.sub("", ev["quote"])[:60] and ev["quote"][:60] not in line:
                            raise ValueError(f"evidence line changed: {src}")
                bad = [x for x in e.get("defects", []) if x not in defect_ids]
                if bad:
                    raise ValueError(f"unknown defect ids {bad}")
                if e["status"] not in STATUS:
                    raise ValueError(f"status {e['status']} not permitted")
                if e["status"] == "SUPERSEDED" and not e.get("superseded_by"):
                    raise ValueError("status SUPERSEDED without superseded_by")
                if e["status"] != "UNCHECKED" and not e.get("status_evidence"):
                    raise ValueError(f"status {e['status']} without status_evidence")
            except Exception as ex:
                errors.append(f"{e['id']}: {type(ex).__name__}: {ex}")
            r.pop("file_list", None)
            out.append(r)
        reg = {"registry_version": ent["registry_version"], "module": mod, "built_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
               "hashing": not a.no_hash, "work_branch_head_at_build": git(top, "log", "-1", "--format=%H %cI").strip(),
               "roots": {k: roots.get(k, "(repository)") for k in ("REPO", "WORK", "EX", "DL", "XDRIVE", "GIT", "DRIVE")},
               "status_values": spec["status_values"], "entries": out}
        if (mdir / "constants.json").exists():
            module_constants[mod] = json.load(open(mdir / "constants.json"))
            reg["constants"] = module_constants[mod]
        json.dump(reg, open(mdir / "REGISTRY.json", "w"), indent=1, ensure_ascii=False)
        merged += out
        print(f"{mod:16s} {len(out):5d} entries  {time.time() - t0:.0f}s", flush=True)
    ids = collections.Counter(e["id"] for e in merged)
    errors += [f"duplicate id {i}" for i, c in ids.items() if c > 1]
    known = set(ids)
    for e in merged:
        if e.get("superseded_by") and e["superseded_by"] not in known:
            errors.append(f"{e['id']}: superseded_by {e['superseded_by']} is not a registry id")
    reg = {"registry_version": "project registry v1 (2026-10-25), phase 2 with hydroacoustics (2026-10-26)", "built_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
           "hashing": not a.no_hash, "work_branch_head_at_build": git(top, "log", "-1", "--format=%H %cI").strip(),
           "roots": {k: roots.get(k, "(repository)") for k in ("REPO", "WORK", "EX", "DL", "XDRIVE", "GIT", "DRIVE")},
           "status_values": spec["status_values"], "kind_values": spec["kind_values"], "modules": spec["modules"],
           "external_registries": spec["external_registries"], "defects": spec["defects"], "module_constants": module_constants, "entries": merged, "build_errors": errors}
    json.dump(reg, open(HERE / "REGISTRY.json", "w"), indent=1, ensure_ascii=False)
    nr = [p for p in tracked if p not in covered]
    json.dump({"tracked": len(tracked), "covered": len(covered), "not_covered": nr}, open(HERE / "coverage_files.json", "w"), indent=0)
    print(f"\n{len(merged)} entries, {len(errors)} errors; {len(covered)} of {len(tracked)} tracked files are in a manifest")
    for x in errors:
        print("ERROR", x)
    sys.exit(1 if errors else 0)


if __name__ == "__main__":
    main()
